#include "sprites.h"
#include "pet.h"

const uint8_t* getBodySprite(uint8_t type, uint8_t variant, bool forceAdult)
{
    static const uint8_t* bodies[4][2] = {
        { CUB_01_50x50, CUB_02_50x50 },
        { CUB_11_50x50, CUB_12_50x50 },
        { CUB_21_50x50, CUB_22_50x50 },
        { CUB_31_50x50, CUB_32_50x50 }
    };
    if (!forceAdult && !pet.evolved) return bodies[0][variant & 1];
    uint8_t idx = type + 1;
    if (idx > 3) idx = 1;
    return bodies[idx][variant & 1];
}

static uint8_t mirrBuf[BODY_SIZE];
static uint8_t mirrEyeBuf[EYE_SIZE];
static uint8_t maskMirrBuf[BODY_SIZE];

// Тут флипаем спрайт по горизонтали
static void mirrorBitmap(const uint8_t* src, uint8_t w, uint8_t h, uint8_t* dst)
{
    uint8_t bw = (w + 7) / 8;
    for (uint8_t r = 0; r < h; r++)
    {
        const uint8_t* s = src + r * bw;
        uint8_t* d = dst + r * bw;
        memset(d, 0, bw);
        for (uint8_t c = 0; c < w; c++)
        {
            if (s[c >> 3] & (0x80 >> (c & 7)))
            {
                uint8_t dc = w - 1 - c;
                d[dc >> 3] |= (0x80 >> (dc & 7));
            }
        }
    }
}

const uint8_t* getMirroredBody(uint8_t type, uint8_t variant, bool forceAdult)
{
    mirrorBitmap(getBodySprite(type, variant, forceAdult), BODY_W, BODY_H, mirrBuf);
    return mirrBuf;
}

const uint8_t* getBodyMask(uint8_t type, uint8_t variant, bool forceAdult)
{
    static const uint8_t* masks[4][2] = {
        { CUB_01_mask_50x50, CUB_02_mask_50x50 },
        { CUB_11_mask_50x50, CUB_12_mask_50x50 },
        { CUB_21_mask_50x50, CUB_22_mask_50x50 },
        { CUB_31_mask_50x50, CUB_32_mask_50x50 }
    };
    if (!forceAdult && !pet.evolved) return masks[0][variant & 1];
    uint8_t idx = type + 1;
    if (idx > 3) idx = 1;
    return masks[idx][variant & 1];
}

const uint8_t* getMirroredMask(uint8_t type, uint8_t variant, bool forceAdult)
{
    mirrorBitmap(getBodyMask(type, variant, forceAdult), BODY_W, BODY_H, maskMirrBuf);
    return maskMirrBuf;
}

const uint8_t* getMirroredEye(uint8_t faceIdx, uint8_t type, bool forceAdult)
{
    mirrorBitmap(getEyeSprite(faceIdx, type, forceAdult), EYE_W, EYE_H, mirrEyeBuf);
    return mirrEyeBuf;
}


