const uint8_t* getEyeSprite(uint8_t faceIdx, uint8_t type, bool forceAdult)
{
    static const uint8_t* eyes[4][8] = {
        { CUB_0_eyeIdle1_15x10, CUB_0_eyeIdle2_15x10, CUB_0_eyeHappy_15x10,
          CUB_0_eyeIdle1_15x10, CUB_0_eyeSleep_15x10, CUB_0_eyeSick_15x10,
          CUB_0_eyeDead_15x10, CUB_1_eyeAtk_15x10 },
        { CUB_1_eyeIdle1_15x10, CUB_1_eyeIdle2_15x10, CUB_1_eyeHappy_15x10,
          CUB_1_eyeIdle1_15x10, CUB_1_eyeSleep_15x10, CUB_1_eyeSick_15x10,
          CUB_1_eyeDead_15x10, CUB_1_eyeAtk_15x10 },
        { CUB_2_eyeIdle1_15x10, CUB_2_eyeIdle2_15x10, CUB_2_eyeHappy_15x10,
          CUB_2_eyeIdle1_15x10, CUB_2_eyeSleep_15x10, CUB_2_eyeSick_15x10,
          CUB_2_eyeDead_15x10, CUB_2_eyeAtk_15x10 },
        { CUB_3_eyeIdle1_15x10, CUB_3_eyeIdle2_15x10, CUB_3_eyeHappy_15x10,
          CUB_3_eyeIdle1_15x10, CUB_3_eyeSleep_15x10, CUB_3_eyeSick_15x10,
          CUB_3_eyeDead_15x10, CUB_3_eyeAtk_15x10 }
    };
    if (!forceAdult && !pet.evolved) return eyes[0][faceIdx];
    uint8_t idx = type + 1;
    if (idx > 3) idx = 1;
    if (faceIdx > FACE_ATTACK) faceIdx = 0;
    return eyes[idx][faceIdx];
}
